// Loading 10,000 products into the change tracker
foreach (var product in products)
{
    dbContext.Products.Add(product);
}

await dbContext.SaveChangesAsync();

// Behind the scenes: 10,000 individual INSERT statements
// each with round-trip overhead and change detection.

protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
{
    optionsBuilder.UseSqlServer(connectionString)
        .UseSqlBatching(options => options.MaxBatchSize = 100);
}

await dbContext.BulkInsertAsync(products, new BulkConfig
{
    BatchSize = 5000,
    PreserveInsertOrder = true,
    SetOutputIdentity = true
});

// 10,000 products inserted in 2 batches
// with minimal change-tracking overhead.

using var bulkCopy = new SqlBulkCopy(_connection);
bulkCopy.DestinationTableName = "dbo.Products";
bulkCopy.BatchSize = 5000;

var dataTable = new DataTable();
dataTable.Columns.Add("Name", typeof(string));
dataTable.Columns.Add("Price", typeof(decimal));

foreach (var product in products)
{
    dataTable.Rows.Add(product.Name, product.Price);
}

await bulkCopy.WriteToServerAsync(dataTable);

// Update 10,000 rows in a single SQL statement
// without loading any entities
await dbContext.Products
    .Where(p => p.CategoryId == oldCategoryId)
    .ExecuteUpdateAsync(s => s
        .SetProperty(p => p.CategoryId, newCategoryId)
        .SetProperty(p => p.UpdatedAt, DateTime.UtcNow));
